"Pod inbound! Reinforcements!":"ক্যাপসুল আসছে! সাহায্য আসছে!",
"Anyone remember why the sky is a portal?":"কারও মনে আছে আকাশ কেন পোর্টাল?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"বলে, শাফটে ঝাঁপ দিলে শত্রুর ওখানে গিয়ে উঠবে। পরীক্ষা করছি না।",
"The Swarm painted their visors red again. Show-offs.":"ঝাঁক আবার ভাইজার লাল রং করেছে। ফুটানি!",
"Ore, ore… when do we get some oil?":"আকরিক, আকরিক… তেল কবে দেবে?",
"I dreamt I was a toaster. It was peaceful.":"স্বপ্নে দেখলাম আমি একটা টোস্টার। শান্তি ছিল।",
"Quiet. Too quiet.":"চুপচাপ। বেশি চুপচাপ।",
"See that? Our base is above the Swarm base again. Portals, man.":"দেখলেন? ঝাঁকের ঘাঁটির ওপরে আবার আমাদের ঘাঁটি। পোর্টাল, ভাই।",
"Diman, if you're reading this — we need a vacation.":"দিমান, এটা পড়লে — আমাদের ছুটি দরকার।",
