"This does not look like a save file (JSON error)":"এটা সেভ ফাইল মনে হচ্ছে না (JSON ত্রুটি)",
"Not a Portal Meteor save or an unsupported version":"Portal Meteor-এর সেভ নয় বা অসমর্থিত সংস্করণ",
"Browser storage is full":"ব্রাউজারের স্টোরেজ ভরে গেছে",
"Battle loaded: {0}":"যুদ্ধ লোড হয়েছে: {0}",
"Autosaved":"অটোসেভ হয়েছে",
"robot war · the sky is a portal":"রোবট যুদ্ধ · আকাশ একটি পোর্টাল",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"উল্কায় স্বাগতম! আপনি কনসোর্টিয়ামের যুদ্ধ রোবট। মাউস দিয়ে চারপাশ দেখুন আর WASD দিয়ে হাঁটুন।",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"জেটপ্যাক: Shift চাপলে লাফ, ধরে রাখলে উড়াল। মাটিতে শক্তি ফিরে আসে।",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"গুলি — বাম বোতাম। নিশানা — ডান বোতাম: বেশি নির্ভুল, জুমসহ। কয়েকটি গুলি চালান।",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"রিলোড — R। গুলি মাঝারি দূরত্বে, ২০–৫০ মিটারে সবচেয়ে জোরে লাগে।",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"রকেট — Q। ট্যাংক ও ভবনের বিরুদ্ধে। একটি রকেট ছুড়ুন।",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"ওপরে রণকৌশলীর আদেশ। সবুজ তীর ধরে ছুটুন: পথে আপনি স্প্রিন্ট করেন। বিন্দু দখল করুন — বীকনের কাছে থাকুন।",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"আপনার স্কোয়াড পেছন সামলায়: বাঁয়ে তাদের ছবি ও স্বাস্থ্য। পিছিয়ে পড়লে তারা অপেক্ষা করতে বলবে।",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — যুদ্ধ না ছেড়ে দ্রুত ইউনিট বদল: লড়াইয়ের সবচেয়ে কাছের স্কোয়াড বা ট্যাংকে ঝাঁপ দিন। চেষ্টা করুন।",
"Next to a tank or turret press E to take control. Or just carry on.":"ট্যাংক বা টারেটের পাশে E চাপুন, নিয়ন্ত্রণ নিতে। অথবা এগিয়ে যান।",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"এবার কৌশল। উপরে ডানদিকে \"◩ কৌশল\" ট্যাপ করুন — যুদ্ধক্ষেত্রের উপর থেকে দেখা দৃশ্য।",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"এবার কৌশল। {0} চাপুন (বা উপরে বাঁদিকে \"◩ কৌশল\") — যুদ্ধক্ষেত্রের উপর থেকে দেখা দৃশ্য।",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"কৌশল মোডে নির্দেশক আপনাকে সাহায্য করে: উপরের বাক্স বলে কী করতে হবে, ফ্রেম বোতাম দেখায়, রিং মানচিত্রে জায়গা চিহ্নিত করে। তার তিনটি পরামর্শ সম্পন্ন করুন।",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"একটি স্কোয়াড নির্বাচন করে সবুজ \"▶ বশ করুন\" বোতামে ট্যাপ করুন — সেই সৈনিক হয়ে আবার যুদ্ধে। আপনি গুলি চালানোর সময় এআই রণকৌশলী নিজেই সেনা চালায়।",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"একটি স্কোয়াড নির্বাচন করে {0} বা সবুজ \"▶ বশ করুন\" চাপুন — সেই সৈনিক হয়ে আবার যুদ্ধে (কিছু নির্বাচিত না থাকলে — নিজের রোবটে)। আপনি গুলি চালানোর সময় এআই রণকৌশলী নিজেই সেনা চালায়।",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"প্রশিক্ষণ শেষ! ঝাঁক আক্রমণ শুরু করছে। শুভকামনা, সৈনিক!",
