"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"আকরিকের নতুন চেহারা: শিরাগুলো কালো ব্যাসল্টে জ্বলজ্বলে পান্নাসবুজ কাটা স্ফটিক, সঙ্গে স্ফুলিঙ্গ ও সবুজ কুয়াশা; এক্সট্র্যাক্টর — ষড়ভুজ বেদি, মৌচাক গম্বুজ ও জালির মিনার, মাথায় সবুজ বাতিঘর (ডোরা ও পতাকা দলের রঙে)",
"New in v6.1":"v6.1-এ নতুন",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield-এর মতো পছন্দের শ্রেণি (U, মৃত্যুর পর সংখ্যা): সম্ভব হলে তুমি সেই শ্রেণিতে রিস্পন করবে",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"প্রথম ব্যক্তির দৃষ্টিতে যান (V — বাইরে/ককপিট); হালকা লক্ষ্য-সহায়তা — সেটিংসে",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"কোর থেকে বেরোনো সহজ: Space — শাফটে, B — ক্যাপসুলে ভূপৃষ্ঠে; মৃত্যুতে ক্ষমতার প্রভাব রিসেট হয়",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"অন্তহীন উন্নতি: জেনারেল ও মার্শাল ★, ক্যারিয়ার লেভেল, অস্ত্রে দক্ষতা ও অ্যাটাচমেন্ট, পদক, দৈনিক চুক্তি — ক্যারিয়ার স্ক্রিন",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"স্ট্র্যাটেজি: মসৃণ হুইল জুম, ইউনিটের আইকন ও লেবেল (Alt — সব), বাঁ দিকে সৈন্য / ভবন প্যানেল",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"ডান বোতাম — চলতে চলতে আক্রমণ, ২× ডান বোতাম — চলন্ত অবস্থায় গুলি করে মার্চ; বিরল আদেশ \"আরও আদেশ ▾\"-এ; বোতাম পুনরাবৃত্ত হয় না",
"New in v6":"v6-এ নতুন",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"শুটার-মানের অস্ত্র: তাৎক্ষণিক গুলি, ৭২০ RPM রাইফেল, MG, রিকয়েল, ডান বোতামে এইম, ম্যাগাজিন ও R রিলোড, হিট মার্কার",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"ভারী মাধ্যাকর্ষণ, সাড়াদায়ক জেটপ্যাক, Z-এ বা আকাশে ২× জেটে ড্যাশ; ইউনিট বদলালে অস্ত্র আর সঙ্গে উড়ে যায় না",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"প্রকৌশলী: প্রকৌশলী বেছে নাও, ভবন বাছো, ব্লুপ্রিন্ট বসাও; আকরিক শিরায় এক্সট্র্যাক্টর; \"আকরিক\"-এ ক্লিক করলে আয় ও তা বাড়ানোর উপায় দেখবে",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"ধূসর বোতামে ক্লিক করলে কারণ ও সমাধান দেখাবে; বড় বোতাম, \"চলমান\" পট্টি, \"▶ নিয়ন্ত্রণ নাও\", Tab-ই একমাত্র মোড কী",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"লাফ ও উল্টে যাওয়া ছাড়া স্ট্র্যাটেজি ক্যামেরা, কার্সরে জুম, টেনে সরানো যায় এমন মিনিম্যাপ",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"নতুন যান: \"Jackal\" রেইডার, \"Grad\" MLRS (হোমিং রকেট), \"Hammer\" মর্টার; Swarm পেল \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"এআই রণকৌশলী আদেশ ধরে রাখে ও ভয়েস স্প্যাম বন্ধ করে; লড়াই তোমার কাছেই আসে; B — স্থানান্তর, Shift+B — লড়াইয়ে; কম্পাস, H — কোন লক্ষ্য",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"স্বাধীন খেলা (K) ও একা চলা (J), F2 প্রিসেট; Esc বিরতি দেয় ও ফেরায়; সেভ: স্লট, ফাইল এক্সপোর্ট ও ইমপোর্ট",
"New in v5.3":"v5.3-এ নতুন",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"উড়ান: উল্কা থেকে দূরে মাধ্যাকর্ষণ বেশি, আকাশে C-তে ব্রেক, থ্রাস্ট আরও তীক্ষ্ণ চালায়; পোর্টালে আর আটকে থাকবে না",
"New in v5":"v5-এ নতুন",
"Endless war by default and battle scale: normal, large, epic":"ডিফল্টে অন্তহীন যুদ্ধ ও যুদ্ধের মাত্রা: সাধারণ, বড়, মহাকাব্যিক",
"Save and load the battle (autosave every 3 minutes)":"যুদ্ধ সেভ ও লোড (প্রতি ৩ মিনিটে অটোসেভ)",
"Squadmates with callsigns: portraits, health and live chatter":"কলসাইনসহ স্কোয়াড: প্রতিকৃতি, স্বাস্থ্য ও জীবন্ত আলাপ",
"Fog of war in strategy, friends and foes outlined differently":"স্ট্র্যাটেজিতে যুদ্ধের কুয়াশা, বন্ধু ও শত্রু আলাদা রঙে চিহ্নিত",
"Camera fly-over when switching, portal aurora instead of rings":"বদলানোর সময় ক্যামেরা উড়ে যায়, বলয়ের বদলে পোর্টালের অরোরা",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"পার্শ্ব-কাজ, আকাশপথে শর্টকাট, রসদসহ প্রথম অভিযানের আবাসস্থল, স্ফটিক, গর্তের বরফ, ধুলোঝড়",
