"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"গ্রেনেড: G ধরে রাখলে বক্রপথ ও বিস্ফোরণ বৃত্ত দেখবে; বোতামে আঙুল টেনে লক্ষ্য ঠিক করো; ছাড়লেই ছোড়া।",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"গ্রেনেড: বক্রপথ ও বিস্ফোরণ বৃত্তের জন্য {0} ধরে রাখো, ছেড়ে ছোড়ো। দূরত্ব — দৃষ্টিকোণে, হুইল — জোর, ডান বোতাম — নিচু হাতে ছোড়া।",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"গ্রেনেড: G ধরে রাখলে উড়ানের বক্রপথ, বিস্ফোরণ বিন্দু ও ব্যাসার্ধ, দূরত্ব দেখবে; ছাড়লে ছোড়া। দূরত্ব দৃষ্টিকোণে, হুইল — জোর, ডান বোতাম — নিচু হাতে ছোড়া",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"গ্রেনেড লাফায় ও ঢাল বেয়ে গড়ায়, ২.৫ সেকেন্ড ফিউজ; ২টি গ্রেনেড, ৯ সেকেন্ডে রিচার্জ; কাছে শত্রুর গ্রেনেড থাকলে সতর্কতা আইকন",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"গ্রেনেড: ধরে রাখো — বক্রপথ ও বিস্ফোরণ বিন্দু, ছাড়ো — ছোড়ো · ট্যাংকের ওভারড্রাইভ",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — ধরে রাখো: বক্রপথ ও বিস্ফোরণ বৃত্ত দেখা যায়, ছাড়লে ছোড়া। ২.৫ সেকেন্ড ফিউজ, ২টি গ্রেনেড।",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"গ্রেনেড ({0}): ধরে রাখো — উড়ানের বক্রপথ, বিস্ফোরণ বিন্দু ও ব্যাসার্ধ, দূরত্ব; ছাড়ো — ছোড়ো; ছোট চাপে সঙ্গে সঙ্গে ছোড়া। দূরত্ব দৃষ্টিকোণে, হুইল — জোর, ডান বোতাম — নিচু হাতে ছোড়া। ফোন: G ধরে আঙুল টানো।",
