"The selected builders do the building. RMB on your building — repair.":"নির্বাচিত প্রকৌশলীরা নির্মাণ করে। নিজের ভবনে ডান বোতাম — মেরামত।",
"Select a builder to build":"নির্মাণ করতে একজন প্রকৌশলী বাছুন",
"Only builders construct. Click a builder on the map or press the button.":"শুধু প্রকৌশলীরা নির্মাণ করে। মানচিত্রে প্রকৌশলীকে ক্লিক করুন বা বোতাম চাপুন।",
"No builders: select the HQ and train a builder.":"কোনো প্রকৌশলী নেই: সদর দপ্তর বেছে একজন প্রকৌশলী অর্ডার করুন।",
