"HQ: train a builder":"সদর দপ্তর: প্রকৌশলী অর্ডার করুন",
"Build keys (Z X C V B N K) pick the nearest builder automatically.":"নির্মাণ কী (Z X C V B N K) নিজেই নিকটতম প্রকৌশলীকে বেছে নেয়।",
"Pick a building to open its production. Or click a building on the map.":"ভবন বাছুন — তার উৎপাদন খুলবে। অথবা মানচিত্রে ভবনে ক্লিক করুন।",
"building {0}%":"নির্মাণ হচ্ছে {0}%",
"queue {0}":"সারি {0}",
"New production buildings are built by builders (\"Build\" tab).":"নতুন উৎপাদন ভবন প্রকৌশলীরা বানায় (\"নির্মাণ\" ট্যাব)।",
