"Advanced: custom class order":"উন্নত: নিজস্ব ক্লাসের ক্রম",
"Voice of hints & curator":"ইঙ্গিত ও গাইডের কণ্ঠ",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"ফোন: তিনটি স্টিক মোড। শুধু বাঁয়ে — «অটো» (জোরালো চুম্বক, দুর্বল গুলি)। শুধু ডানে — নিশানা নিজে চালু হয়, জোরালো চুম্বক, নিখুঁত গুলি। দুটোই — নিশানা নেই, চুম্বক ও নির্ভুলতা কম। ডানের 👁 বোতাম HUD লুকায়/ফেরায়।",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"ফোন: স্ট্র্যাটেজি সরল — শুধু প্রকৌশলী ও ভবন। বাঁয়ে কার্ড (প্রকৌশলী, সদর দপ্তর, ব্যারাক…): ট্যাপ করলে ক্যামেরা সেখানে যায়, নিচের বারে কী বানাবে/তৈরি করবে দেখায়। «যুদ্ধে» — বাঁ-উপরে। সেনা নিজেই লড়ে। পূর্ণ স্ট্র্যাটেজি — সেটিংস → ফোন।",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"নিয়ন্ত্রণ নেওয়া — দুটি সুইচ: «স্কোয়াড» ও «যান» (ফোনে যান ডিফল্টে বন্ধ — এআই চালায়)। যান বন্ধ থাকলে নিজেদের যানের পাশে E (ফোনে — ডানের বোতাম) চেপে তার কামানে বসো: যান নিজে চলে, তুমি গুলি করো। পুরনো নিজস্ব ক্লাস ক্রম «উন্নত»-তে আছে। নিয়ন্ত্রণ নিলে ইউনিট রেডিওতে সাড়া দেয়।",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"স্মার্ট ইঙ্গিত: মৌলিক ইঙ্গিত ২য় চালুর পর নিজেই নিভে যায়, তবে যে ফিচার কখনো ব্যবহার করোনি গেম তার কথা মনে করাবে। সুইচ: মৌলিক / উন্নত / বিরল, আর আলাদা — ইঙ্গিত ও গাইডের কণ্ঠ।",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"হত্যা থেকে রিফ্লেক্স চার্জ হয় (টানা হত্যায় বেশি চার্জ হয়)। সঙ্গীরা পিছিয়ে পড়লে বা মারা গেলে AI রণকৌশলী তোমার কাছে নতুনদের নামিয়ে দেয় (সাধারণ রিইনফোর্সমেন্টের চেয়ে দামি)। v7.2gfx-এর গ্রাফিক্স ও শব্দ যুক্ত হয়েছে: ধোঁয়ার কুণ্ডলীসহ বিস্ফোরণ, ধোঁয়া, ধ্বংসাবশেষ, খাদ ও গর্তের অ্যাকুস্টিক্স। বিল্ডের তারিখ এখন আসল।",
