"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"ক্যারিয়ার ও সেভ অপরিবর্তিত থাকে। যুদ্ধে একই মেনু উপরে ডানের «🛠 মেনু» বোতাম{0}।",
