"Cinema: split screen":"সিনেমা: স্প্লিট স্ক্রিন",
"strategist bot left, shooter bot right":"বাঁয়ে রণকৌশলী বট, ডানে শুটার বট",
"Cinema: everything built":"সিনেমা: সব নির্মিত",
"both bases built and upgraded — for footage":"দুই ঘাঁটিই নির্মিত ও আপগ্রেড — ফুটেজের জন্য",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"সিনেমা মোড — স্প্লিট স্ক্রিন: বাঁয়ে রণকৌশলী বট (ঘাঁটি ও সেনার ওপর থেকে দেখা), ডানে শুটার বট প্রথম ব্যক্তির চোখে। নিচে বোতাম (এবং কী S, P): «স্প্লিট স্ক্রিন» ও «★ সব নির্মিত» — ফুটেজের জন্য দুই ঘাঁটিই নির্মিত ও আপগ্রেড।",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"কোর আর উল্কার ভেতর দিয়ে সুড়ঙ্গ আর নেই — উল্কা এখন নিরেট, লড়াই শুধু উপরিভাগে।",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"ফোন: 👁 HUD লুকায় কিন্তু জেটপ্যাক, ⇆, স্টিক আর লক্ষ্য মার্কার রেখে দেয়। \"◎ লক্ষ্য\" (শুধু ডান আঙুল) — স্পষ্টতই আরও জোরালো ও চওড়া চুম্বক; তিন মোডের চুম্বক — সেটিংস → নিয়ন্ত্রণ → \"উন্নত\"। যানের কামানে বোতামের নাম \"নামো\"।",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"প্রশিক্ষণ: ফোনে শুধু ফোনের প্রশিক্ষণ, পিসিতে শুধু পিসির। ৪টিই \"🛠 ডেভেলপার\" মেনুতে। ডেভেলপার মোড আর অস্ত্রাগার এখন একই মেনু (লড়াইয়ে — উপরে ডানে \"🛠 মেনু\", পিসিতে F8)।",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"গ্রাফিক্স স্টাইল \"Dendy (৮-বিট)\" ও \"১৬-বিট\": সেটিংস → গ্রাফিক্স → \"গ্রাফিক্স স্টাইল\" (বিস্তারিত — ⚙ বোতাম)। ম্যাচের প্রথম ~১০ সেকেন্ডে FPS ২৪-এর নিচে হলে Dendy নিজে থেকে চালু হয় (২০-এর নিচে — আরও বড় পিক্সেল, ১২০ লাইন); \"স্বাভাবিকে ফিরো\" নোটিশ স্থায়ীভাবে স্বাভাবিক গ্রাফিক্স ফিরিয়ে দেয়। মেনুতে তোমার নিজের পছন্দই সবসময় প্রাধান্য পায়।",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"পরিবেশের ৩ডি মডেল (ধ্বংসাবশেষ, ভাঙা যান, দুর্গ) — শুধু ভালো রেটিং পাওয়াগুলো, চাহিদা অনুযায়ী লোড হয়। বন্ধ করতে: সেটিংস → গ্রাফিক্স → \"নতুন ৩ডি পরিবেশ মডেল\"।",
