"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"সৈনিকদের নির্মাণ: নিজেদের নির্মাণস্থলে E (ফোনে \"প্রবেশ\") — সৈনিক নিজেই বানায়, কাছের সঙ্গীরা সাহায্য করে। প্রকৌশলীরা ব্যস্ত থাকলে রণকৌশলী নিজেই সাহায্য চাইবে — \"নির্মাণস্থল\" মার্কার।",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"রণকৌশলীর চিহ্ন: রণকৌশলী তোমার কাছের শত্রুদলের ওপর ⌖ বসায় — ৮ সেকেন্ড পর সেখানে আর্টিলারি আঘাত হানে, আর কাছের নিজেদের \"গ্রাদ\" এমএলআরএস ভলি ছোড়ে। স্ট্র্যাটেজি মোড থেকে তোমার নিজের আর্টিলারি আঘাতেও \"গ্রাদ\"-এর সহায়তা মেলে।",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"কার্গো কন্টেইনার আর বিধ্বস্ত স্যাটেলাইটে অস্ত্রভান্ডার (📦 ৭০ মি থেকে দেখা যায়): E — ৯০ সেকেন্ডের ভারী মেশিনগান, অগ্নিসংযোগকারী গুলি বা রকেট, সঙ্গে পূর্ণ গ্রেনেড। হামাগুড়ি: Ctrl — শুয়ে পড়ো / উঠে দাঁড়াও (নিচু, স্থির নিশানা, কিন্তু ধীর)।",
