"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ এখনই খেলুন\" — মেনুর প্রথম বোতাম: পোর্টাল-আকাশের নিচ দিয়ে ছোট্ট উড়ান আর সোজা লড়াইয়ে (যেকোনো কী বা ট্যাপে এড়িয়ে যাও)।",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"আঘাত আঘাতের মতোই লাগে: ধাতব শব্দ আর স্ফুলিঙ্গ, ক্রসহেয়ারে কিল মার্কার (মাথায় — হলুদ), ×N ধারা, বিস্ফোরণ থেকে মসৃণ কাঁপুনি, মূল কিলে স্লো-মোশন। কাঁপুনি, স্লো-মোশন আর ইঙ্গিত সেটিংসে বন্ধ করা যায়।",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"ম্যাচের ফল: সময়, ধ্বংস, সেরা ধারা, ★ MVP আর সেরা স্কোয়াড, ম্যাচ কার্ড — \"⇪ শেয়ার\", PNG বা গেমের লিঙ্ক।",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"সম্পদের নিচে বাঁয়ে \"এখন কী করবে\" ইঙ্গিত: স্ট্র্যাটেজিস্টের আদেশ, দখলের বিন্দু, ঝাঁকের আক্রমণ। ✕ বা F7 — গুটিয়ে নাও।",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"ট্যাব বন্ধ বা লুকালে লড়াই নিজে থেকেই সেভ হয় — মেনুতে \"⟲ চালিয়ে যান\"।",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"নতুনটা ভালো না লাগলে v7.5 \"🕘 গেমের সংস্করণ\" মেনুতে থেকে গেছে। নামহীন পরিসংখ্যান (নাম বা ইমেইল ছাড়া) এখন পাঠানো হয়; বন্ধ করতে — সেটিংসে।",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"এখনই খেলুন\", আঘাতের অনুভূতি, শেয়ার কার্ডসহ ম্যাচের ফল, \"কী করবে\" ইঙ্গিত, স্বয়ংক্রিয় সেভ",
"and older: v7.5, v7.4, milestones v1–v7.0":"এবং পুরোনো: v7.5, v7.4, মাইলফলক v1–v7.0",
"New in v7.6":"v7.6-এ নতুন",
"NEW IN v7.6":"v7.6-এ নতুন",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"ম্যাচের আগে দল বাছো: \"কনসোর্টিয়াম\" (শক্তিচালিত বর্মে ভারী পদাতিক, বর্ম ও আর্টিলারি) বা \"ঝাঁক\" (গতি, ড্রোনের ঝাঁক, বিকৃতিসহ ভারী গুলি)। এআই অন্যটি খেলে। পছন্দ মনে রাখা হয়।",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"প্রতিটি দলের নিজস্ব যান ও অনন্য সুবিধা আছে: কনসোর্টিয়ামের — ট্যাংক \"রাইনো\" আর \"সেরামাইট প্লেট\", বাঁকের — \"ড্রোনের ঝাঁক\" আর \"ফেজ জেটপ্যাক\"। বট ম্যাচে ভারসাম্য যাচাই করা হয়েছে।",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"বিস্ফোরণের গর্ত: আর্টিলারি, রকেট আর ট্যাংকের কামান উল্কায় গর্ত খোঁড়ে — এগুলোর ভেতর দিয়ে হাঁটা ও গাড়ি চালানো যায়, আড়ালও নেওয়া যায়।",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"সৈনিকের জন্য থার্ড-পারসন ভিউ (V, মনে রাখা হয়; ফোনে — নিয়ন্ত্রণ) আর যানবাহনের মসৃণ ক্যামেরা, কামানের গোলা কোথায় পড়বে তার চিহ্নসহ।",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"পছন্দ না হলে v7.6 \"🕘 গেমের সংস্করণ\" মেনুতে রয়ে গেছে।",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"ম্যাচের আগে বেছে নেওয়ার সুবিধাসহ কনসোর্টিয়াম / বাঁক পক্ষ, বিস্ফোরণের গর্ত, থার্ড-পারসন ভিউ",
"and older: v7.6, v7.5, milestones v1–v7.0":"এবং পুরোনো: v7.6, v7.5, মাইলফলক v1–v7.0",
