"Anomaly ahead! The vein is singing — go around!":"সামনে অসংগতি! শিরা গাইছে — এড়িয়ে যাও!",
"Hear that hum? A singing vein. Keep clear!":"গুনগুন শুনছ? গায়ক শিরা। কাছে যেয়ো না!",
"Anomaly! The air is swirling — a whirlpool, go around!":"অসংগতি! বাতাস পাক খাচ্ছে — ঘূর্ণি, এড়িয়ে যাও!",
"Rocks floating in the air… A whirlpool! Stay out!":"পাথর বাতাসে ভাসছে… ঘূর্ণি! ঢুকো না!",
"Anomaly ahead — it is crackling with current!":"সামনে অসংগতি — বিদ্যুতে কড়কড় করছে!",
"Rods and lightning — a Crackler. It loves armour!":"দণ্ড আর বিদ্যুৎ — কড়কড়ে। বর্ম ওর খুব পছন্দ!",
