"Careful, a Brazier underfoot!":"সাবধান, পায়ের নিচে আংটা!",
"Anomaly — green mist! Acid, hold your breath!":"অসংগতি — সবুজ কুয়াশা! অ্যাসিড, নিঃশ্বাস আটকাও!",
"The mist is drifting our way, go around!":"কুয়াশা আমাদের দিকে ভেসে আসছে, এড়িয়ে যাও!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"অসংগতি! বাতাস কাচের মতো — লেন্স, গুলি বাঁকায়!",
"Everything is warping… a Lens nearby!":"সব বেঁকে যাচ্ছে… কাছেই লেন্স!",
"Ha! An enemy walked right into the anomaly!":"হা! শত্রু সোজা অসংগতিতে ঢুকে পড়েছে!",
"Got him! Lure them into anomalies!":"ধরেছি! ওদের অসংগতিতে টেনে আনো!",
"Beautiful zap! One less tin can.":"দারুণ ঝলক! একটা টিনের কৌটো কমল।",
"The anomaly got me!":"অসংগতি আমাকে ছুঁয়ে ফেলেছে!",
"Ow! Don't go in there!":"আউ! ওখানে যেয়ো না!",
"Discharged! It is dormant now.":"নিঃশেষ করে দিয়েছি! এখন ওটা সুপ্ত।",
"Clear, the anomaly is discharged.":"পরিষ্কার, অসংগতি নিঃশেষিত।",
"They say veins hide artifacts. Only first the vein sings…":"লোকে বলে শিরায় আর্টিফ্যাক্ট লুকানো থাকে। তবে আগে শিরা গায়…",
"Throw a bolt first, then walk. Old habit.":"আগে বল্টু ছোড়ো, তারপর হাঁটো। পুরোনো অভ্যাস।",
"throw a bolt":"বল্টু ছোড়ো",
"📦 Supply drop: landing in 4 seconds":"📦 সরবরাহ ক্রেট: ৪ সেকেন্ডে নামছে",
"full magazines":"ম্যাগাজিন ভরা",
"grenades":"গ্রেনেড",
"rockets ×{0}":"রকেট ×{0}",
"weapon parts":"অস্ত্রের যন্ত্রাংশ",
