"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"মাটিতে আঙুল ~০.৩ সে ধরে রাখো — ফোন কাঁপবে আর হলুদ বলয় আসবে — তারপর না তুলে টানো: বক্স তৈরি হবে। অথবা ডানের \"বক্স\" বোতাম। স্কোয়াডে শুধু ট্যাপ করলেও চলে।",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"আইফোনে পূর্ণ স্ক্রিনের জন্য: \"শেয়ার\" ⬆ → \"হোম স্ক্রিনে যোগ করুন\" — গেম Safari-র বার ছাড়াই খুলবে।",
"Open portal-meteor.pages.dev for that.":"এজন্য portal-meteor.pages.dev খোলো।",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"ট্যাপ — নির্বাচন · মাটিতে ট্যাপ — চলো · ধরে রাখো — আদেশ মেনু · ধরে টানো — বক্স · ২ আঙুল — জুম",
"Robo-ninja":"রোবো-নিনজা",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"আততায়ী নায়িকা: ব্লিঙ্ক-ড্যাশ, কাতানা, শুরিকেন। নিজেই শত্রুর এলাকায় টেলিপোর্ট করে রোবট কাটে। প্রতি পক্ষে ১টি।",
"Shadow protocol":"\"ছায়া\" প্রোটোকল",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"গবেষণা: ব্যারাকে রোবো-নিনজা খোলে। তৈরি মেক কারখানা লাগবে।",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"নায়িকা (প্রতি পক্ষে ১টি): নিজেই শত্রুর এলাকায় টেলিপোর্ট করে রোবট কাটে; নিয়ন্ত্রণ নিয়ে হাতে খেলা যায়।",
"is ready. She works on her own (AUTO) — possess her to play manually":"তৈরি। নিজেই কাজ করে (অটো) — হাতে খেলতে নিয়ন্ত্রণ নাও",
"Robo-ninja ready for action":"রোবো-নিনজা লড়াইয়ের জন্য প্রস্তুত",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ রিকনিসান্স: শত্রুর রোবো-নিনজা এসেছে!",
"Warning! The enemy has a robo-ninja. Stay together":"সতর্কতা! শত্রুর রোবো-নিনজা আছে। একসাথে থাকো",
"cyber blinks":"সাইবার ব্লিঙ্ক",
"Too far for a dash — get closer or teleport":"ড্যাশের জন্য অনেক দূর — কাছে যাও বা টেলিপোর্ট করো",
"point ":"বিন্দু ",
"enemy group":"শত্রু দল",
"order":"আদেশ",
"nearby":"কাছেই",
"Zone cleared":"এলাকা পরিষ্কার",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ নিনজা দ্বন্দ্ব! আঘাতের ঠিক আগে ব্লক করলে প্রতিহত হয়, ব্লিঙ্কে এড়ানো যায়। ঝাঁকুনির ঝলকে নজর রাখো",
"The two ninjas have met in a duel!":"দুই নিনজা দ্বন্দ্বে মুখোমুখি!",
"⚔ Duel won! Our ninja prevails":"⚔ দ্বন্দ্বে জয়! আমাদের নিনজা এগিয়ে",
"⚔ Duel lost…":"⚔ দ্বন্দ্বে হার…",
"ninja duel":"নিনজা দ্বন্দ্ব",
"POSTURE BROKEN":"ভঙ্গি ভেঙে গেছে",
"Teleport":"টেলিপোর্ট",
"Teleport: aim at the ground (up to 150 m)":"টেলিপোর্ট: মাটিতে লক্ষ্য করো (১৫০ মি পর্যন্ত)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ অটো: নিজেই শত্রুর এলাকায় লাফিয়ে কাটে। স্টিক / WASD ১.৫ সে থামায়",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ হাতে: শত্রুতে ট্যাপ — ড্যাশ ও কাটা, সোয়াইপ — আঘাত, 🛡 — ব্লক",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ হাতে: বাম বোতাম — কাতানা, ডান বোতাম — ব্লক, Shift — ব্লিঙ্ক, Q — শুরিকেন, G — টেলিপোর্ট",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ নিনজা: শত্রুর ওপর ট্যাপ — ছুটে গিয়ে আঘাত, ডানদিকে সোয়াইপ — তলোয়ারের কোপ, ● — আঘাত, 🛡 — ব্লক (ঠিক সময়ে = প্যারি), ⇑ — ব্লিঙ্ক, ✦ — শুরিকেন, ◎ — টেলিপোর্ট, AUTO — নিজে নিজে",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ নিনজা: বাম বোতাম — কাতানা (ধরে রাখো — ভারী আঘাত), ডান বোতাম — ব্লক (ঠিক সময়ে = প্যারি), Shift/Z — ব্লিঙ্ক, Q — শুরিকেন, G — ক্রসহেয়ারে টেলিপোর্ট, শূন্যে জাম্প — ডাবল জাম্প / দেয়াল-দৌড়, {0} — AUTO",
