"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 ডানদিকে — রেডিও পোর্টাল মিটিওর: লড়াইয়ের সময় EDMITRY-র গান।",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — রেডিও পোর্টাল মিটিওর: লড়াইয়ের সময় EDMITRY-র গান। [ ] — ট্র্যাক।",
"Radio Portal Meteor (EDMITRY): volume":"রেডিও পোর্টাল মিটিওর (EDMITRY): ভলিউম",
"Radio: start by itself in battle":"রেডিও: লড়াইয়ে নিজে থেকে চালু হোক",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"রোবো-নিনজা: কাতানাধারী সাইবর্গ। ব্যারাকে \"শ্যাডো প্রটোকল\" গবেষণায় খোলে (মেক কারখানা লাগে)। নিজেই শত্রুর এলাকায় টেলিপোর্ট করে, শত্রুদের টুকরো করে (রক্ত নেই — স্ফুলিঙ্গ), ছুটে আক্রমণ করে, শুরিকেন ছোড়ে, শত্রু নিনজার সঙ্গে দ্বন্দ্বে নামে। তার নিয়ন্ত্রণ নাও — AUTO মোড বা ম্যানুয়াল নিয়ন্ত্রণ (ফোনে আলাদা বোতাম)।",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"রেডিও পোর্টাল মিটিওর: EDMITRY-র ১০৩টি ট্র্যাক সরাসরি গেমে। কী 5 (বদলানো যায়), ফোনে — ☰ → সেটিংস → শব্দ। ভলিউম ও \"লড়াইয়ে নিজে থেকে চালু\" সেটিংসে; বিস্ফোরণ ও রেডিও কণ্ঠে গান নিচু হয়ে যায়।",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"নতুন ভাষা: উজবেক ও তাজিক — সম্পূর্ণ; চীনা, স্প্যানিশ, পর্তুগিজ — আংশিক। মেনুতে \"নতুন ম্যাচ\"-এর পাশে নতুন ভাষা নির্বাচক।",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"ফোন: \"আইকন লুকাও\" 👁 বাকি বোতামগুলো ডান প্রান্তে গোছানো সারিতে জড়ো করে; পোর্ট্রেটে আর গায়ে গায়ে লাগে না; আইফোন — গেম আর Safari-র ইশারার সঙ্গে সংঘর্ষ করে না, আর \"শেয়ার → হোম স্ক্রিনে যোগ করুন\" দিলে পূর্ণ পর্দায় চলে।",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1 থেকে: কোণে ☰ মেনু (বিরতি, আবার শুরু, প্রশিক্ষণ, গ্রাফিক্স), অটো-Dendy নেই, ফোনে ✋ অ্যাকশন বোতাম। v7.8.1 ও v7.8 \"🕘 গেমের সংস্করণ\" মেনুতে থাকছে।",
