"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"ঝাঁক। ২২০ মি পর্যন্ত একটি বিন্দু বাছো — ২৪ সেকেন্ডে বেরোনোর পথ ভেদ হবে। ১০ সেকেন্ড আগে শত্রু গুমগুম শব্দ শুনবে ও ধুলো দেখবে।",
"Squads into the tunnel":"স্কোয়াড — সুড়ঙ্গে",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"ঝাঁক। গর্তের ৭০ মি-র মধ্যের (ও নির্বাচিত) স্কোয়াডগুলো সুড়ঙ্গ দিয়ে যায়। অথবা স্কোয়াড নির্বাচন করে গর্তে ডান বোতাম/ট্যাপ করো।",
"Swarm only":"শুধু ঝাঁকের জন্য",
"Needs a Tunnel burrow":"সুড়ঙ্গ গর্ত দরকার",
"Still being built":"এখনও তৈরি হচ্ছে",
"Exit already open":"বেরোনোর পথ আগেই খোঁড়া",
"No exit yet — \"Dig the exit\" in the burrow panel":"বেরোনোর পথ এখনও নেই — গর্তের প্যানেলে \"বেরোনোর পথ খোঁড়ো\"",
"Too close to the HQ or a point — no digging here":"সদর দপ্তর বা বিন্দুর খুব কাছে — এখানে খোঁড়া যায় না",
"Rocks in the way":"পাথর বাধা দিচ্ছে",
"Selected squads go into the nearest open tunnel and come out at the other end":"নির্বাচিত স্কোয়াড নিকটতম খোলা সুড়ঙ্গে ঢুকে অন্য প্রান্তে বেরোয়",
"Into tunnel":"সুড়ঙ্গে",
"\"Bastion\"":"\"বাস্টিয়ন\"",
"Super-heavy tank":"অতিভারী ট্যাংক",
"\"Reaper\"":"\"রিপার\"",
"Walker":"ওয়াকার",
"Assembly hall":"সংযোজন হল",
"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"কনসোর্টিয়াম। লড়াইয়ের ১২:০০ থেকে। এখানে অতিভারী ট্যাংক \"বাস্টিয়ন\" বানানো হয় (প্রতি বাহিনীতে একটি)।",
"Incubator":"ইনকিউবেটর",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"ঝাঁক। ১২:০০ থেকে। এখানে ওয়াকার \"রিপার\" বেড়ে ওঠে (প্রতি বাহিনীতে একটি)।",
"Super-heavy tank \"Bastion\"":"অতিভারী ট্যাংক \"বাস্টিয়ন\"",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"কনসোর্টিয়াম। বস: ১৫০০০ কাঠামো, কামান, ২টি মেশিনগান, রকেট। খুব ধীর। দুর্বল স্থান — পেছন। প্রতি বাহিনীতে একটি।",
"Walker \"Reaper\"":"ওয়াকার \"রিপার\"",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"ঝাঁক। বস: ১২৫০০ কাঠামো, বিকৃতি রশ্মি, পদাঘাত। বাধা ডিঙিয়ে যায়। দুর্বল স্থান — পেটের নিচের কোর। প্রতি বাহিনীতে একটি।",
"Limit: 1 per army":"সীমা: প্রতি বাহিনীতে ১",
