"ours":"আমাদের",
"key":"কী",
"Strip: ⟳ to rotate, or drag from the target along the run":"স্ট্রিপ: ⟳ ঘোরাতে, অথবা লক্ষ্য থেকে আক্রমণের দিক বরাবর টেনে নাও",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"স্ট্রিপ: মাউস হুইল বা R ঘোরাতে, অথবা লক্ষ্য থেকে আক্রমণের দিক বরাবর টেনে নাও",
