"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"ঝাঁক। গর্ত থেকে ৭০ m-এর মধ্যে থাকা স্কোয়াড (এবং নির্বাচিতগুলো) এবং নির্বাচিত হালকা/মাঝারি যান (\"জ্যাকাল\", \"হ্যামার\", \"গ্র্যাড\") সুড়ঙ্গ দিয়ে যায়। অথবা: নির্বাচন করে গর্তে RMB/ট্যাপ করো।",
"Air strikes":"বিমান আঘাত",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"কার্পেট বোমাবর্ষণ ও ন্যাপাম: লক্ষ্য নির্ধারণ, স্ট্রিপ ঘোরানো, শত্রুর সতর্কতা, যুদ্ধ থেকে ডাকা",
"Terrain and lakes":"ভূখণ্ড ও হ্রদ",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"লাভা পোড়ায়, বরফ পিছলায়, আগুনে মিথেন বিস্ফোরিত হয়, পাহাড়ের হ্যাঙ্গার আড়াল",
"Swarm: tunnels":"ঝাঁক: সুড়ঙ্গ",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"তুমি ঝাঁক খেলছ: সুড়ঙ্গ গর্ত, ২২০ m পর্যন্ত বেরোনোর পথ, ধুলোর সতর্কতা, স্কোয়াড ও যান সুড়ঙ্গ দিয়ে",
"Consortium: fortifications":"কনসোর্টিয়াম: প্রতিরক্ষা",
