"{0} — turn off the AI strategist and command yourself":"{0} — এআই রণকৌশলী বন্ধ করে নিজে কমান্ড করুন",
"{0} — third-person view":"{0} — তৃতীয় ব্যক্তির দৃশ্য",
"{0} — reload early":"{0} — আগেভাগে রিলোড করুন",
