"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"আপনার ইউনিটরা সাহায্য চায় ও পুরস্কার দেয়, নায়করা কোয়েস্ট দেয়, থমকে থাকা ফ্রন্ট অভিযানে ভাঙা হয়",
"A request":"অনুরোধ",
"Breakthrough":"যুদ্ধের মোড় ঘোরানো",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"আপনার ইউনিটরা মাঝে মাঝে সাহায্য চায়: রেডিওতে কণ্ঠ, \"অনুরোধ\" কার্ড আর ✋ চিহ্ন। কোনো স্কোয়াড আটকা পড়েছে — তার কাছের শত্রুদের ধ্বংস করুন। পুরস্কার: ঘাঁটি থেকে ক্যাপসুলে সৈনিক, বাগির ডিকি থেকে অস্ত্র, গানারের আসন বা কক্ষপথ থেকে কভার। না চাইলে — ✕ বা শুধু উপেক্ষা করুন।",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"প্রবীণ স্কাউট \"পেঁচা\" কোয়েস্ট দিচ্ছে। Y — নিন (N — প্রত্যাখ্যান)। ★ চিহ্নে যান, পাহারাদারদের সরান, পাইলটের পাশে ৩ s থাকুন — সে আপনার স্কোয়াডে যোগ দেবে।",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"ফ্রন্ট থেমে গেছে — সদর দপ্তর মোড় ঘোরানোর অভিযান দিচ্ছে। Y — নিন। কাছে শত্রু ছাড়া রিলে ৮ s ধরে রাখুন: শত্রুর মানচিত্র ৬০ s দৃশ্যমান। জেনারেটর — শত্রুর টারেট ২ মিনিট নীরব। স্ট্র্যাটেজিস্টে — \"স্কোয়াডকে দিন\"। শত্রুও এটা পারে: ⚠ খেয়াল রাখুন।",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"আপনার ইউনিটরা সাহায্য চায়: \"অনুরোধ\" কার্ড আর ✋ চিহ্ন। আটকা স্কোয়াডের কাছের শত্রুদের ধ্বংস করুন — পুরস্কার পাবেন। ✕ — এড়িয়ে যান।",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"নায়ক \"পেঁচা\" কোয়েস্ট দিচ্ছে — \"নিন\"-এ ট্যাপ করুন। ★-এ যান, পাহারাদারদের সরান, পাইলটের পাশে থাকুন।",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"ফ্রন্ট থেমে গেছে — \"নিন\"-এ ট্যাপ করুন আর রিলে ৮ s ধরে রাখুন: শত্রুর মানচিত্র এক মিনিট খুলবে।",
