"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"সদর দপ্তরের পাশের সাইলো: এখান থেকে ক্যাপসুল, সরবরাহ বাক্স ও বোমারু বিমান আকাশ পোর্টাল দিয়ে লক্ষ্যে রওনা হয়। এর ওপর কিছু বানানো যায় না।",
"Economy":"অর্থনীতি",
"Key building":"মূল স্থাপনা",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"দুর্বল জায়গা — পিছন (ইঞ্জিন): ক্ষতি ×{0}। কামান, ২টি মেশিনগান টারেট, রকেট পড; খুব ধীরে ঘোরে — পাশ থেকে ঘুরে আক্রমণ করো।",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"দুর্বল জায়গা — পেটের নিচের জ্বলজ্বলে কোর: নিচ থেকে ক্ষতি ×{0}। বিকৃতি রশ্মি ও এলাকাজুড়ে পদাঘাত; বাধা ডিঙিয়ে যায় — দূরত্ব রাখো, দলা পাকিয়ে থেকো না।",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"কার্যকর: বিমান বোমা ও আর্টিলারি (×{0}), রকেট (×{1}), কার্পেট বোমাবর্ষণ; গুলি প্রায় অকেজো (×{2})।",
"Faction":"পক্ষ",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"দ্রুত যান, ড্রোনের ঝাঁক, সুড়ঙ্গ ও পুনর্জন্ম। পদাতিক হালকা কিন্তু দ্রুত; কামান ও রেল বেশি জোরে আঘাত করে।",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"শক্তিচালিত বর্মে ভারী পদাতিক, কংক্রিট বাধা, মেরামত ও আর্টিলারি। ধীর কিন্তু মজবুত।",
