"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. ভয়েস সহ স্ক্রিন রেকর্ডিং চালু করুন (পিসিতে OBS, ফোনে মাইক সহ বিল্ট-ইন স্ক্রিন রেকর্ডার) এবং এখানে \"মতামত মোড\" চালু করুন।",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. খেলুন আর জোরে ভাবুন: কী বোঝা যাচ্ছে না, কী বিরক্ত করছে, কী মজার। কোণে সংস্করণ, সময় ও FPS দেখায় — এগুলো দিয়ে রেকর্ডিং আর নোট মেলানো হয়।",
"3. When something matters — take a note: PC ":"3. কিছু গুরুত্বপূর্ণ হলে নোট নিন: পিসি ",
" (press ":" (আবার চাপুন ",
